import{_ as a}from"./chunks/ind-public-chart.BeYuNPiS.js";import{_ as e,o,c as i,ag as r}from"./chunks/framework.CxkNbRKf.js";const g=JSON.parse('{"title":"Indicators and time series","description":"","frontmatter":{},"headers":[],"relativePath":"admin-guide/content/indicators.md","filePath":"admin-guide/content/indicators.md","lastUpdated":1793155456000}'),d={name:"admin-guide/content/indicators.md"};function n(s,t,h,l,c,u){return o(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="indicators-and-time-series" tabindex="-1">Indicators and time series <a class="header-anchor" href="#indicators-and-time-series" aria-label="Permalink to &quot;Indicators and time series&quot;">​</a></h1><p>NADA publishes <strong>indicators</strong> (summary measures such as a poverty rate or <em>GDP per capita</em>) together with their <strong>data</strong>. When an indicator&#39;s values have a time reference (annual, quarterly, monthly…), it forms a <strong>time series</strong>. NADA treats both the same way, so this guide uses &quot;indicator&quot; for both.</p><p>A published indicator has its own catalog page with documentation, an interactive chart, a data table, downloads and an API for its data.</p><p><img src="'+a+'" alt="Indicator page in the catalog, Chart &amp; data tab"></p><div class="info custom-block"><p class="custom-block-title">Requirements</p><ul><li><strong>NADA 5.6</strong> or later.</li><li><strong>MongoDB</strong>, which stores the indicator data used by charts, tables, the Data API and embeds. See <a href="/nada-documentation/installation-guide/installation-mongodb.html">MongoDB setup</a>. MongoDB needs <strong>PHP 8.1+</strong>.</li><li>A NADA account with permission to add and publish entries.</li></ul><p>You can document an indicator&#39;s metadata without MongoDB, but its data cannot be uploaded or shown.</p></div><hr><h2 id="what-users-see" tabindex="-1">What users see <a class="header-anchor" href="#what-users-see" aria-label="Permalink to &quot;What users see&quot;">​</a></h2><p>Each published indicator has a catalog page with these tabs:</p><table tabindex="0"><thead><tr><th>Tab</th><th>Shows</th></tr></thead><tbody><tr><td><strong>Series description</strong></td><td>The indicator&#39;s documentation: definition, methodology, sources, coverage</td></tr><tr><td><strong>Chart &amp; data</strong></td><td>An interactive chart, with filters for each dimension (country, year, sex…)</td></tr><tr><td><strong>Table</strong></td><td>The same data as a table, for example countries by years</td></tr><tr><td><strong>Data API</strong></td><td>How to get the data with the API, and a data explorer</td></tr><tr><td><strong>Data structure</strong></td><td>The columns of the data, what each one means, and the codes it uses</td></tr><tr><td><strong>Downloads</strong></td><td>Documents and links attached to the indicator (shown only when there are some)</td></tr></tbody></table><p>See <a href="./indicators-frontend.html">Catalog frontend</a> for a full tour.</p><hr><h2 id="how-it-fits-together" tabindex="-1">How it fits together <a class="header-anchor" href="#how-it-fits-together" aria-label="Permalink to &quot;How it fits together&quot;">​</a></h2><p>An indicator in NADA is built from four parts. Each part depends on the ones above it. The examples use the World Bank indicator <strong>SI.POV.DDAY</strong>, <em>Poverty headcount ratio at $3.00 a day (2021 PPP) (% of population)</em>, which is used throughout this guide.</p><table tabindex="0"><thead><tr><th>Part</th><th>What it is</th><th>Example</th></tr></thead><tbody><tr><td><strong>Codelist</strong></td><td>A list of allowed codes and their labels</td><td>Country codes: <code>AGO</code> = Angola, <code>ALB</code> = Albania…</td></tr><tr><td><strong>Data structure (DSD)</strong></td><td>The columns of the data, the role of each (indicator, country, year, value…), and which codelist each column uses. One data structure can be shared by many indicators.</td><td><code>INDICATOR</code>, <code>INDICATOR_LABEL</code>, <code>REF_AREA</code> (uses the country codelist), <code>YEAR</code>, <code>VALUE</code></td></tr><tr><td><strong>Indicator</strong></td><td>The catalog entry: its metadata (series description) and the data structure it uses. It can optionally be linked to a <strong>source database</strong> entry describing the database it comes from.</td><td><em>Poverty headcount ratio at $3.00 a day</em> (<code>SI.POV.DDAY</code>)</td></tr><tr><td><strong>Data</strong></td><td>The observations: one value per row, for each combination of indicator, country and year</td><td><code>SI.POV.DDAY, ALB, 2012, 1.8</code></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Sample files</p><p>The sample files for SI.POV.DDAY (data, data structure, metadata and thumbnail) are in <a href="https://github.com/ihsn/nada-documentation/tree/main/examples/indicators" target="_blank" rel="noreferrer"><code>examples/indicators</code></a>. Download them all as <a href="https://github.com/ihsn/nada-documentation/raw/main/examples/indicators/try_indicators.zip" target="_blank" rel="noreferrer">try_indicators.zip</a>. The Metadata Editor documentation uses the same indicator.</p></div><p>The metadata is stored in NADA&#39;s database (MySQL / SQL Server). The data is stored in MongoDB. For more on each part, the column roles and a glossary, see <a href="./indicators-concepts.html">Key concepts</a>.</p><hr><h2 id="choose-a-workflow" tabindex="-1">Choose a workflow <a class="header-anchor" href="#choose-a-workflow" aria-label="Permalink to &quot;Choose a workflow&quot;">​</a></h2><p>There are three ways to publish an indicator. All three produce the same result in NADA.</p><table tabindex="0"><thead><tr><th>Workflow</th><th>Where you work</th><th>Best for</th></tr></thead><tbody><tr><td><strong><a href="#metadata-editor-to-nada">Metadata Editor → NADA</a></strong> · <em>Recommended</em></td><td>In the Metadata Editor. Publishing sends everything to NADA.</td><td>Most users. You can check the data before publishing, and updating an indicator is just re-publishing it.</td></tr><tr><td><strong><a href="#directly-in-nada">Directly in NADA</a></strong></td><td>In the NADA admin interface</td><td>A few indicators, quick corrections, or catalogs without the Metadata Editor</td></tr><tr><td><strong><a href="#using-the-nada-api">NADA API</a></strong></td><td>Your own scripts (R, Python or any HTTP client)</td><td>Many indicators at once, and scheduled updates</td></tr></tbody></table><h3 id="metadata-editor-to-nada" tabindex="-1">Metadata Editor → NADA <a class="header-anchor" href="#metadata-editor-to-nada" aria-label="Permalink to &quot;Metadata Editor → NADA {#metadata-editor-to-nada}&quot;">​</a></h3><p>You document the indicator, define its data structure and import its data in the <strong>Metadata Editor</strong>. Publishing then sends the metadata, data structure (with its codelists) and data to NADA in one step.</p><p>How to do this in the editor: <a href="https://worldbank.github.io/metadata-editor-docs/documenting_indicator.html" target="_blank" rel="noreferrer">Documenting indicators (Metadata Editor documentation)</a>.</p><p><strong>What NADA needs:</strong></p><ul><li>MongoDB installed and configured: see <a href="/nada-documentation/installation-guide/installation-mongodb.html">MongoDB setup</a>.</li><li>A NADA user account with permission to add and publish entries, and an <strong>API key</strong> for that account. The editor uses the key in its catalog connection to NADA.</li></ul><p><strong>After publishing, check in NADA:</strong></p><ol><li>The indicator appears in <strong>Studies → Manage studies</strong>.</li><li>Its data structure appears under <strong>Settings → Data structures</strong>.</li><li>The indicator&#39;s <strong>Indicator data</strong> tab shows the uploaded rows.</li><li>The catalog page shows the <strong>Chart &amp; data</strong> tab.</li></ol><h3 id="directly-in-nada" tabindex="-1">Directly in NADA <a class="header-anchor" href="#directly-in-nada" aria-label="Permalink to &quot;Directly in NADA {#directly-in-nada}&quot;">​</a></h3><p>You create everything in the NADA admin interface:</p><ol><li>Import the data structure with its codelists, or create them: see <a href="/nada-documentation/admin-guide/web-ui/data-structures.html">Data structures</a> and <a href="/nada-documentation/admin-guide/web-ui/codelists.html">Codelists</a>.</li><li>Create the indicator in <strong>Studies → Manage studies → Add study</strong>, from a metadata JSON file or from scratch.</li><li>Enter or check its metadata.</li><li>Attach the data structure and upload the data as a CSV file.</li><li>Publish the indicator.</li></ol><p>Steps 2–5 are covered in <a href="./indicators-admin.html">Create an indicator in NADA</a>. To try it with sample files, follow the <a href="./indicators-tutorial.html">tutorial</a>.</p><h3 id="using-the-nada-api" tabindex="-1">Using the NADA API <a class="header-anchor" href="#using-the-nada-api" aria-label="Permalink to &quot;Using the NADA API {#using-the-nada-api}&quot;">​</a></h3><p>Your script makes the same calls that the Metadata Editor makes when it publishes:</p><table tabindex="0"><thead><tr><th>Step</th><th>Endpoint</th></tr></thead><tbody><tr><td>1. Import codelists</td><td><code>POST api/admin/codelists/import_json</code></td></tr><tr><td>2. Import the data structure</td><td><code>POST api/admin/data_structures/import_json</code> (JSON) or <code>POST api/admin/data_structures/import</code> (SDMX XML)</td></tr><tr><td>3. Create the indicator with its metadata</td><td><code>POST api/datasets/create/timeseries/{idno}</code></td></tr><tr><td>4. Upload the data file (large files)</td><td><code>POST api/uploads/init</code>, then <code>POST api/uploads/chunk/{upload_id}</code></td></tr><tr><td>5. Import the data</td><td><code>POST api/admin/timeseries/data/{idno}/import</code> with the file or <code>upload_id</code>, and the data structure&#39;s <code>dsd_idno</code></td></tr></tbody></table><p>All of these calls need an API key with administrator rights. The <a href="/nada-documentation/admin-guide/api-tools.html">NADAR</a> (R) and <a href="/nada-documentation/admin-guide/api-tools.html">PyNADA</a> (Python) packages do not cover these calls yet. Until they do, call the endpoints directly.</p><hr><h2 id="rules-that-apply-to-every-workflow" tabindex="-1">Rules that apply to every workflow <a class="header-anchor" href="#rules-that-apply-to-every-workflow" aria-label="Permalink to &quot;Rules that apply to every workflow&quot;">​</a></h2><ul><li><strong>Uploading data replaces all of the indicator&#39;s data.</strong> It never appends. To add one year, upload the complete file again.</li><li><strong>Data structures are shared.</strong> When a data structure changes, every indicator that uses it is marked <strong>sync pending</strong>. Its chart, table, Data API and embeds are hidden until it is resynced (the <strong>Resync</strong> button on its <strong>Indicator data</strong> tab) or its data is uploaded again. Before you edit a data structure, check how many indicators use it (shown in the data structures list).</li><li><strong>Switching or detaching an indicator&#39;s data structure deletes its uploaded data.</strong> Upload the data again afterwards.</li><li><strong>IDNOs connect everything.</strong> The indicator&#39;s IDNO and its data structure&#39;s IDNO must be the same in the Metadata Editor, in your scripts and in NADA.</li></ul><hr><h2 id="built-in-indicators-widgets-and-the-data-tables-api" tabindex="-1">Built-in indicators, widgets and the data tables API <a class="header-anchor" href="#built-in-indicators-widgets-and-the-data-tables-api" aria-label="Permalink to &quot;Built-in indicators, widgets and the data tables API&quot;">​</a></h2><p>NADA has two other features that can show data. They are separate from built-in indicators:</p><ul><li><strong><a href="/nada-documentation/admin-guide/widgets.html">Widgets</a></strong> embed custom charts, maps or data viewers that you build yourself on catalog pages.</li><li><strong><a href="./data-api.html">The data tables API</a></strong> publishes tabular data to MongoDB with its own data dictionary, mainly for statistical tables.</li></ul><p>Use built-in indicators when the data fits a data structure: you get the chart, table, Data API and downloads without writing any code.</p><hr><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="./indicators-concepts.html">Key concepts</a>: the parts of an indicator, column roles and a glossary</li><li><a href="./indicators-data-api.html">Indicator data API</a>: read an indicator&#39;s data with scripts</li><li><a href="./indicators-tutorial.html">Tutorial</a>: publish SI.POV.DDAY step by step, directly in NADA</li><li><a href="./indicators-admin.html">Create an indicator in NADA</a>: create an indicator, attach a data structure and upload data</li><li><a href="./indicators-frontend.html">Catalog frontend</a>: what users see on a published indicator page</li><li><a href="/nada-documentation/admin-guide/web-ui/codelists.html">Codelists</a> and <a href="/nada-documentation/admin-guide/web-ui/data-structures.html">Data structures</a></li><li><a href="./indicators-wdi-example.html">Example: publishing WDI series with R and Python</a> (NADA 5.0 example, being revised)</li></ul>',46)])])}const b=e(d,[["render",n]]);export{g as __pageData,b as default};
